function sma(values, p) { return values.map((_,i) => i < p-1 ? NaN : values.slice(i-p+1,i+1).reduce((a,b)=>a+b,0)/p); }
function ema(values,p) { const out=Array(values.length).fill(NaN), k=2/(p+1); if(values.length<p)return out; out[p-1]=values.slice(0,p).reduce((a,b)=>a+b,0)/p; for(let i=p;i<values.length;i++)out[i]=values[i]*k+out[i-1]*(1-k); return out; }
function rsi(values,p=14) { const out=Array(values.length).fill(NaN); if(values.length<=p)return out; let g=0,l=0; for(let i=1;i<=p;i++){const d=values[i]-values[i-1];if(d>=0)g+=d;else l-=d;} let ag=g/p,al=l/p; out[p]=al===0?100:100-100/(1+ag/al);for(let i=p+1;i<values.length;i++){const d=values[i]-values[i-1];ag=(ag*(p-1)+Math.max(d,0))/p;al=(al*(p-1)+Math.max(-d,0))/p;out[i]=al===0?100:100-100/(1+ag/al)}return out; }
