function renderLeverageGuard(m){const out=$('leverageGrid');if(!out)return;const exchange={binance:{name:'Binance USDⓈ-M',mmr:.004},okx:{name:tx('OKX USDT 永续','OKX USDT perpetual'),mmr:.005},coinbase:{name:'Coinbase Perpetuals',mmr:.006}}[leverageExchange],entry=m.close,mmr=exchange.mmr,data=state.candles.slice(-60),swings=[];for(let i=19;i<data.length;i++){const window=data.slice(i-19,i+1),hi=Math.max(...window.map(x=>x.high)),lo=Math.min(...window.map(x=>x.low));swings.push((hi-lo)/data[i].close)}const sorted=swings.sort((a,b)=>a-b),p80=sorted.length?sorted[Math.floor((sorted.length-1)*.8)]:0;const atrFloor=(m.atr/entry)*2,bufferPct=Math.max(p80*.35,atrFloor,.003),buffer=entry*bufferPct;const method=$('leverageMethod');if(method)method.textContent=tx(`已应用 ${exchange.name} 的比较用近似参数（维持保证金 ${(mmr*100).toFixed(2)}%）。自适应缓冲：近 ${data.length} 根 K 线的 20 根高低振幅 P80 为 ${(p80*100).toFixed(2)}%，取其 35% 与 2×ATR 中较大者；当前缓冲 ${(bufferPct*100).toFixed(2)}%（${money(buffer)}）。`,`Using ${exchange.name} comparison parameters (maintenance margin ${(mmr*100).toFixed(2)}%). Adaptive buffer: the P80 20-candle high/low range across the latest ${data.length} candles is ${(p80*100).toFixed(2)}%; the buffer uses the greater of 35% of that value and 2×ATR. Current buffer ${(bufferPct*100).toFixed(2)}% (${money(buffer)}).`);out.innerHTML=[10,30,50,100].map(lev=>{const long=entry*(1-1/lev+mmr),short=entry*(1+1/lev-mmr);return `<div class="lev-row"><b>${lev}×</b><span><small>${tx('多 · 理论强平','Long · theoretical liq.')}</small>${money(long)}</span><span><small>${tx('多 · 缓冲警戒','Long · buffer warning')}</small>${money(long+buffer)}</span><span><small>${tx('空 · 理论强平','Short · theoretical liq.')}</small>${money(short)}</span><span><small>${tx('空 · 缓冲警戒','Short · buffer warning')}</small>${money(short-buffer)}</span></div>`}).join('')}
function trainCrossMarket(rows){if(rows.length<120)return null;const split=Math.floor(rows.length*.8),w=[0,0,0],train=rows.slice(0,split),test=rows.slice(split);let b=0;for(let e=0;e<90;e++)for(const r of train){const p=sigmoid(b+r.x.reduce((s,v,i)=>s+v*w[i],0)),err=r.y-p;b+=.018*err;r.x.forEach((v,i)=>w[i]+=.018*err*v)}const score=x=>sigmoid(b+x.reduce((s,v,i)=>s+v*w[i],0));const accuracy=test.filter(r=>(score(r.x)>=.5?1:0)===r.y).length/test.length;return {prob:score(rows.at(-1).x),accuracy,n:train.length}}
async function loadCorrelation(){const status=$('correlationStatus'),out=$('correlationOutput');if(!out)return;status.textContent='正在对齐 BTC、SPY、QQQ 的共同交易日并训练…';try{const r=await fetch('/api/correlation-history');const d=await r.json();if(!r.ok)throw new Error(d.error||'request failed');const quoteCard=(name,ticker,q)=>{const delta=q.last-q.previous,up=delta>=0;return `<article class="index-card ${up?'up':'down'}"><span>${name} · ${ticker}</span><b>${q.last.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}</b><div><em>${up?'+':'−'}${Math.abs(delta).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}</em><em>${up?'+':'−'}${(Math.abs(delta)/q.previous*100).toFixed(2)}%</em></div><small>最近收盘</small></article>`};const cards=$('indexTickerCards');if(cards)cards.innerHTML=quoteCard('标普 500','SPY',d.indexQuotes.spy)+quoteCard('纳斯达克 100','QQQ',d.indexQuotes.qqq);const byDate=arr=>new Map(arr.map(x=>[new Date(x.time).toISOString().slice(0,10),x.close])),btc=byDate(d.btc),spy=byDate(d.spy),qqq=byDate(d.qqq),dates=[...btc.keys()].filter(k=>spy.has(k)&&qqq.has(k)).sort(),rows=[];for(let i=1;i<dates.length-1;i++){const prev=dates[i-1],cur=dates[i],next=dates[i+1],br=(btc.get(cur)/btc.get(prev)-1)*100,sr=(spy.get(cur)/spy.get(prev)-1)*100,qr=(qqq.get(cur)/qqq.get(prev)-1)*100;rows.push({br,sr,qr,y:btc.get(next)>btc.get(cur)?1:0,x:[sr,qr,br]})}const recent=rows.slice(-60),fit=trainCrossMarket(rows),corrSPY=pearson(recent.map(x=>x.br),recent.map(x=>x.sr)),corrQQQ=pearson(recent.map(x=>x.br),recent.map(x=>x.qr)),p=fit?Math.round(fit.prob*100):null;out.innerHTML=`<div class="corr-stat"><span>BTC × SPY（60日）</span><b class="${corrSPY>=0?'bull':'bear'}">${corrSPY>=0?'+':''}${corrSPY.toFixed(2)}</b><small>${corrSPY>=.3?'正相关较明显':corrSPY<=-.3?'负相关较明显':'相关性偏弱'}</small></div><div class="corr-stat"><span>BTC × QQQ（60日）</span><b class="${corrQQQ>=0?'bull':'bear'}">${corrQQQ>=0?'+':''}${corrQQQ.toFixed(2)}</b><small>${corrQQQ>=.3?'正相关较明显':corrQQQ<=-.3?'负相关较明显':'相关性偏弱'}</small></div><div class="corr-stat wide"><span>跨市场模型：下一交易日 BTC 看多概率</span><b class="${p>=50?'bull':'bear'}">${p===null?'--':p.toFixed(2)+'%'}</b><small>${fit?`SPY、QQQ 与 BTC 当日收益特征 · 样本外准确率 ${(fit.accuracy*100).toFixed(2)}% · 训练 n=${fit.n}`:'共同交易日不足'}</small></div>`;status.textContent=`数据已按共同交易日对齐 · ${d.cached?'缓存数据':'刚更新'} · 相关性会随窗口变化，不能单独作为开仓信号。`}catch(e){status.textContent=`美股联动模块暂不可用：${e.message}`}}
