function draw(){const cv=$('chart'),rect=cv.getBoundingClientRect(),dpr=devicePixelRatio||1,w=rect.width,h=rect.height,d=visibleCandles();if(!d.length||!w)return;cv.width=w*dpr;cv.height=h*dpr;const c=cv.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,w,h);const P={l:18,r:74,t:15,b:30},cw=w-P.l-P.r,ch=h-P.t-P.b;let lo=Math.min(...d.map(x=>x.low)),hi=Math.max(...d.map(x=>x.high));const closes=d.map(x=>x.close),ma20=ema(closes,20),ma50=ema(closes,50),ma200=ema(closes,200);for(const a of [ma20,ma50,ma200])for(const v of a)if(Number.isFinite(v)){lo=Math.min(lo,v);hi=Math.max(hi,v)}const margin=(hi-lo||1)*.075;lo-=margin;hi+=margin;const x=i=>P.l+i/(d.length-1)*cw,y=v=>P.t+ch-(v-lo)/(hi-lo)*ch;c.font='11px system-ui';c.lineWidth=1;c.strokeStyle='rgba(144,169,199,.14)';c.fillStyle='#75849a';for(let g=0;g<5;g++){const yy=P.t+g*ch/4;c.beginPath();c.moveTo(P.l,yy);c.lineTo(P.l+cw,yy);c.stroke();c.fillText((hi-(hi-lo)*g/4).toFixed(2),P.l+cw+9,yy+4)}const grad=c.createLinearGradient(0,P.t,0,P.t+ch);grad.addColorStop(0,'rgba(0,212,170,.22)');grad.addColorStop(1,'rgba(0,212,170,0)');c.beginPath();d.forEach((v,i)=>i?c.lineTo(x(i),y(v.close)):c.moveTo(x(i),y(v.close)));c.lineTo(x(d.length-1),P.t+ch);c.lineTo(x(0),P.t+ch);c.closePath();c.fillStyle=grad;c.fill();const line=(a,color)=>{c.beginPath();let s=false;a.forEach((v,i)=>{if(!Number.isFinite(v)){s=false;return}if(s)c.lineTo(x(i),y(v));else{c.moveTo(x(i),y(v));s=true}});c.strokeStyle=color;c.lineWidth=1.3;c.stroke()};line(ma20,'#4b9fff');line(ma50,'#d69b2d');line(ma200,'#a970ff');c.beginPath();d.forEach((v,i)=>i?c.lineTo(x(i),y(v.close)):c.moveTo(x(i),y(v.close)));c.strokeStyle='#00d4aa';c.lineWidth=2;c.stroke();const hiI=d.reduce((b,v,i)=>v.high>d[b].high?i:b,0),loI=d.reduce((b,v,i)=>v.low<d[b].low?i:b,0);const mark=(i,v,label,color,above)=>{const xx=x(i),yy=y(v);c.save();c.strokeStyle=color+'99';c.setLineDash([4,4]);c.beginPath();c.moveTo(P.l,yy);c.lineTo(P.l+cw,yy);c.stroke();c.setLineDash([]);c.fillStyle=color;c.font='600 11px system-ui';c.textAlign=xx>w-180?'right':'left';c.fillText(`${label} ${money(v)}`,xx+(xx>w-180?-7:7),yy+(above?-8:15));c.restore()};mark(hiI,d[hiI].high,tx('最高','High'),'#ffcb65',true);mark(loI,d[loI].low,tx('最低','Low'),'#52d5f4',false);for(let g=0;g<5;g++){const i=Math.round(g*(d.length-1)/4);c.fillStyle='#75849a';c.textAlign='center';c.fillText(time(d[i].time),x(i),h-8)}if(chartSelection){const a=Math.min(chartSelection.start,chartSelection.end),b=Math.max(chartSelection.start,chartSelection.end);c.fillStyle='rgba(75,159,255,.13)';c.fillRect(x(a),P.t,x(b)-x(a),ch);c.strokeStyle='rgba(135,190,255,.9)';c.setLineDash([4,4]);c.strokeRect(x(a),P.t,x(b)-x(a),ch);c.setLineDash([])}if(hoverIndex!==null){const v=d[hoverIndex],xx=x(hoverIndex),yy=y(v.close);c.save();c.strokeStyle='rgba(222,237,255,.42)';c.setLineDash([3,4]);c.beginPath();c.moveTo(xx,P.t);c.lineTo(xx,P.t+ch);c.moveTo(P.l,yy);c.lineTo(P.l+cw,yy);c.stroke();c.setLineDash([]);c.fillStyle='#fff';c.beginPath();c.arc(xx,yy,3.5,0,Math.PI*2);c.fill();c.restore()}}
(() => {const cv=$('chart');const index=e=>{const r=cv.getBoundingClientRect(),d=visibleCandles();return Math.max(0,Math.min(d.length-1,Math.round(((e.clientX-r.left-18)/(r.width-92))*(d.length-1))))};const stats=()=>{if(!chartSelection)return;const d=visibleCandles(),a=Math.min(chartSelection.start,chartSelection.end),b=Math.max(chartSelection.start,chartSelection.end),s=d.slice(a,b+1),hi=Math.max(...s.map(v=>v.high)),lo=Math.min(...s.map(v=>v.low)),change=(s.at(-1).close/s[0].open-1)*100;const el=$('selectionStats');if(el)el.innerHTML=`<b>${tx('已选区段','Selected')}</b> ${pointTime(s[0].time)} — ${pointTime(s.at(-1).time)} · <span class="high">${tx('最高','High')} ${money(hi)}</span> · <span class="low">${tx('最低','Low')} ${money(lo)}</span> · <span class="${change>=0?'bull':'bear'}">${tx('涨跌','Return')} ${pct(change)}</span>`};cv.addEventListener('pointerdown',e=>{chartSelection={start:index(e),end:index(e)};cv.setPointerCapture(e.pointerId);stats();draw()});cv.addEventListener('pointermove',e=>{if(!chartSelection||!cv.hasPointerCapture(e.pointerId))return;chartSelection.end=index(e);stats();draw()});cv.addEventListener('pointerup',e=>{if(cv.hasPointerCapture(e.pointerId))cv.releasePointerCapture(e.pointerId);stats()});cv.addEventListener('dblclick',()=>{chartSelection=null;const el=$('selectionStats');if(el)el.textContent=tx('拖拽图表可框选区段，显示最高、最低及涨跌幅。','Drag on chart to select a period: high, low and return.');draw()})})();
