function projectionValidationData(){const d=state.candles;if(d.length<60)return null;const minutes={"1m":1,"5m":5,"15m":15,"30m":30,"1h":60,"2h":120,"4h":240,"1d":1440}[state.interval]||15,current=metrics(d),targetMinutes=Math.abs(current.score)>=75?60:Math.abs(current.score)>=50?40:20,horizon=Math.max(1,Math.round(targetMinutes/minutes)),start=Math.max(50,d.length-121),end=d.length-horizon;let hit=0,total=0;for(let i=start;i<end;i++){const predicted=metrics(d.slice(0,i+1)).score>=0,actual=d[i+horizon].close>=d[i].close;hit+=predicted===actual?1:0;total++}return{targetMinutes,accuracy:total?hit/total*100:0,total}}
updateSignalProjectionValidation=function(){const box=$('signalProjection'),data=projectionValidationData();if(!box||!data)return;const prefix=box.querySelector('[data-projection-validation]'),value=box.querySelector('[data-projection-accuracy]'),suffix=box.querySelector('[data-projection-validation-suffix]');if(!prefix||!value||!suffix)return;prefix.textContent=tx(`按当前 ATR 波动与规则信号强度推算；预计方向在约 ${data.targetMinutes} 分钟的滚动历史准确度`,`Derived from current ATR and rule strength; direction is tested over about ${data.targetMinutes} minutes of rolling historical validation`);value.textContent=` ${data.accuracy.toFixed(2)}%`;suffix.textContent=tx(` · n=${data.total}。目标价本身不保证到达。`,` · n=${data.total}; the target itself is not guaranteed.`)};
renderSignalProjection=function(){const signal=$('signal'),reason=$('signalReason'),m=state.candles.length?metrics(state.candles):null;if(!signal||!reason||!m)return;let box=$('signalProjection');if(!box){box=document.createElement('section');box.id='signalProjection';box.className='signal-projection';box.innerHTML='<span data-projection-heading></span><div><b data-projection-direction></b><em data-projection-duration></em><strong><span data-projection-target-label></span> <button class="help-dot" type="button" data-projection-tip aria-label="Target price explanation">!</button> <b data-projection-target-value></b></strong></div><small><span data-projection-validation></span><b data-projection-accuracy></b><span data-projection-validation-suffix></span></small>';reason.after(box)}const long=m.score>=0,strength=Math.abs(m.score),last=state.ticker?.last||m.close,move=m.atr*(1.05+Math.min(1.25,strength/100)),target=last+(long?move:-move),duration=strength>=75?tx('约 45–90 分钟','about 45–90 min'):strength>=50?tx('约 20–60 分钟','about 20–60 min'):tx('约 10–30 分钟','about 10–30 min'),tip=long?tx('预计目标价表示：按当前“做多”方向与上方预计持续时长，推测价格可能上涨到的研究目标位；不是保证到达或成交的价格。','Estimated target: a research level the price may rise to during the projected long duration; not a guaranteed fill or outcome.'):tx('预计目标价表示：按当前“做空”方向与上方预计持续时长，推测价格可能下跌到的研究目标位；不是保证到达或成交的价格。','Estimated target: a research level the price may fall to during the projected short duration; not a guaranteed fill or outcome.');box.className=`signal-projection ${long?'bull':'bear'}`;box.querySelector('[data-projection-heading]').textContent=tx('方向研究估算','Directional research estimate');box.querySelector('[data-projection-direction]').textContent=long?tx('做多','Long'):tx('做空','Short');box.querySelector('[data-projection-duration]').textContent=`${tx('预计持续','Estimated duration')} ${duration}`;box.querySelector('[data-projection-target-label]').textContent=tx('预计目标价','Estimated target');box.querySelector('[data-projection-target-value]').textContent=money(target);const tipButton=box.querySelector('[data-projection-tip]');tipButton.dataset.tip=tip;tipButton.setAttribute('aria-label',tx('预计目标价说明','Target price explanation'));updateSignalProjectionValidation()};

