loadForecasts=async function(){const grid=$('forecastGrid'),status=$('forecastStatus');if(!grid)return;status.textContent=tx('正在获取训练样本并进行滚动训练…','Fetching samples and training rolling models…');try{const r=await fetch('/api/forecast-history'),data=await r.json();if(!r.ok)throw new Error(data.error||'history request failed');const jobs=uiLang==='zh'?[['30分','intraday',2],['1小时','intraday',4],['2小时','intraday',8],['半天','intraday',48],['1天','intraday',96],['2天','intraday',192],['1周','daily',7],['半个月','daily',15],['1个月','daily',30],['半年','daily',180]]:[['30m','intraday',2],['1h','intraday',4],['2h','intraday',8],['12h','intraday',48],['1d','intraday',96],['2d','intraday',192],['1w','daily',7],['15d','daily',15],['1m','daily',30],['6m','daily',180]];grid.innerHTML=jobs.map(([label,key,h])=>{const fit=trainProbability(data[key].map(x=>x.close),h);if(!fit)return `<div class="forecast-item muted"><span>${label}</span><b>${tx('样本不足','Insufficient sample')}</b></div>`;const long=fit.prob*100;return `<div class="forecast-item"><span>${label}</span><b class="${long>=50?'bull':'bear'}">${long.toFixed(2)}% ${tx('看多','bullish')}</b><small>${tx('看空','bearish')} ${(100-long).toFixed(2)}% · ${tx('验证','validation')} ${(fit.accuracy*100).toFixed(2)}% · n=${fit.train}</small></div>`}).join('');status.textContent=tx(`双模型集成 · ${data.cached?'缓存历史样本':'刚更新'} · 概率为方向条件概率，不是收益预测。`,`Two-model ensemble · ${data.cached?'cached samples':'updated'} · Directional probability, not a return forecast.`)}catch(e){status.textContent=`${tx('概率模块暂不可用','Probability module unavailable')}：${e.message}`}};
