const microPredictionBase=microPrediction;
microPrediction=function(m){microPredictionBase(m);const closes=state.candles.map(x=>x.close);let hit=0,total=0;for(let i=6;i<closes.length;i++){const predicted=closes[i-1]>=closes[i-4],actual=closes[i]>=closes[i-1];hit+=predicted===actual?1:0;total++}const accuracy=total?hit/total*100:0;const entry=document.querySelector('.micro-direction span'),note=document.querySelector('.micro-direction small');if(entry)entry.innerHTML=`${tx('未来 5 分钟建议观察买入价','Suggested observation entry for next 5m')} <strong>${entry.querySelector('strong')?.textContent||'--'}</strong>`;if(note)note.innerHTML=`${tx('下一分钟','Next 1m')} ${note.textContent.split('·')[0]?.replace(/^.*? /,'')} · ${tx('下一五分钟','Next 5m')} ${note.textContent.split('·')[1]?.replace(/^.*? /,'')} · <b>${tx('5分钟方向历史验证','5m directional historical validation')} ${accuracy.toFixed(2)}%</b>`};
function addGlobalHelp(){const signalCard=$('signal')?.closest('article');addHelp(signalCard?.querySelector('h2'),'该数值将 EMA 趋势、MACD 动量、RSI 和波动位置标准化为 −100 至 +100。正值偏多、负值偏空，绝对值越大代表规则一致性越高；不代表必然涨跌。','This score combines EMA trend, MACD momentum, RSI and volatility position on a −100 to +100 scale. Positive is bullish, negative bearish; magnitude is rule agreement, not certainty.');addHelp(document.querySelector('.change-card h2'),'显示当前价格相对于 5 分钟、15 分钟、1 小时、4 小时和 1 日前的涨跌幅，用于快速比较不同观察窗口。','Shows return versus 5m, 15m, 1h, 4h and 1d ago for fast cross-window comparison.');addHelp(document.querySelector('.forecast-card h2'),'概率模型通过历史价格特征估计未来方向。它只能提供研究线索，不能保证收益或替代仓位和风险管理。','The probability model estimates future direction from historical price features. It is research context only, not a profit guarantee or a substitute for risk management.');addHelp(document.querySelector('.correlation-card h2'),'比较 BTC 与 SPY、QQQ 的滚动相关和跨市场特征，辅助识别联动环境；相关性会随时间变化。','Compares rolling BTC correlations with SPY and QQQ. It helps identify market linkage; correlations vary over time.');addHelp(document.querySelector('.leverage-card h2'),'强平和缓冲价是基于当前价格、杠杆与近期震荡的近似研究值。实际交易所以标记价格、仓位档位和保证金模式为准。','Liquidation and buffer prices are research approximations based on current price, leverage and recent volatility. Actual exchange values depend on mark price, tiers and margin mode.');document.querySelectorAll('#indicators .metric>span').forEach(el=>addHelp(el,`${el.childNodes[0]?.textContent||'该指标'}用于观察趋势、动量或波动，不应单独作为开仓依据。`,`${el.childNodes[0]?.textContent||'This indicator'} describes trend, momentum or volatility and should not be used as a stand-alone entry rule.`))}
