function renderFixedRuleSignal(){if(fixedRuleSignal.candles.length<200)return;const m=metrics(fixedRuleSignal.candles),[label,cls]=classification(m.score),signal=$('signal'),reason=$('signalReason'),indicators=$('indicators');if(signal){signal.textContent=`${label} ${m.score>0?'+':''}${m.score.toFixed(2)}`;signal.className=`signal ${cls}`}if(reason)reason.innerHTML=`<span><b class="signal-indicator ${m.close>=m.e20?'bull':'bear'}">EMA20 ${money(m.e20)}</b><i>·</i><b class="signal-indicator ${m.close>=m.e50?'bull':'bear'}">EMA50 ${money(m.e50)}</b><i>·</i><b class="signal-indicator ${m.rsi>=50?'bull':'bear'}">RSI(14) ${m.rsi.toFixed(2)}</b><i>·</i><b class="signal-indicator ${m.macd>=0?'bull':'bear'}">MACD ${m.macd.toFixed(2)}</b></span>`;if(indicators)indicators.innerHTML=[['EMA20',money(m.e20)],['EMA50',money(m.e50)],['EMA200',money(m.e200)],['RSI(14)',m.rsi.toFixed(2)],['布林位置',(m.bb*100).toFixed(2)+'%'],['ATR(14)',money(m.atr)]].map(([name,value])=>`<div class="metric"><span>${name}</span><b>${value}</b></div>`).join('');const sl=$('sl'),tp=$('tp');if(sl)sl.textContent=money(m.close-m.atr*1.5);if(tp)tp.textContent=money(m.close+m.atr*3);let basis=$('fixedRuleBasis');if(!basis&&reason){basis=document.createElement('small');basis.id='fixedRuleBasis';basis.className='fixed-rule-basis';reason.after(basis)}if(basis)basis.textContent=`${fixedRuleBasisText()} · 最近收盘 ${pointTime(fixedRuleSignal.closedAt)}`}
async function loadFixedRuleSignal(force=false){if(fixedRuleSignal.loading)return;fixedRuleSignal.loading=true;try{const source=state.source||'okx',query=new URLSearchParams({source,interval:fixedRuleSignal.interval,limit:'201'}),response=await fetch('/api/market?'+query),data=await response.json();if(!response.ok)throw data;const candles=data.candles.slice(0,-1).slice(-200),closedAt=candles.at(-1)?.time,key=`${data.source}:${fixedRuleSignal.interval}:${closedAt}`;if(candles.length===200&&(force||key!==`${fixedRuleSignal.source}:${fixedRuleSignal.interval}:${fixedRuleSignal.closedAt}`)){fixedRuleSignal.candles=candles;fixedRuleSignal.source=data.source;fixedRuleSignal.closedAt=closedAt}renderFixedRuleSignal()}catch{}finally{fixedRuleSignal.loading=false}}
(()=>{const card=$('signal')?.closest('article'),heading=card?.querySelector('h2');if(!card||!heading||$('fixedRuleControl'))return;const control=document.createElement('label');control.id='fixedRuleControl';control.className='fixed-rule-control';control.innerHTML=`<span>信号基准</span><select aria-label="信号基准周期"><option value="5m">5分钟</option><option value="15m">15分钟</option><option value="1h">1小时</option></select>`;const select=control.querySelector('select');select.value=fixedRuleSignal.interval;select.onchange=()=>{fixedRuleSignal.interval=select.value;fixedRuleSignal.candles=[];fixedRuleSignal.closedAt=0;localStorage.setItem('btc_rule_signal_interval',select.value);loadFixedRuleSignal(true)};heading.after(control);$('source')?.addEventListener('change',()=>loadFixedRuleSignal(true));loadFixedRuleSignal(true);setInterval(()=>loadFixedRuleSignal(),15_000)})();
