/* Main chart: render true OHLC candles (body + high/low wicks) rather than a
   close-only line.  This preserves hammer / shooting-star shapes directly in
   the price data while keeping the existing MA, range-selection and tooltip UI. */
function drawCandlestickChart(){
  const cv=$('chart'),rect=cv?.getBoundingClientRect(),d=visibleCandles();
  if(!cv||!rect||d.length<2)return;
  const dpr=devicePixelRatio||1,w=rect.width,h=rect.height;
  cv.width=Math.round(w*dpr);cv.height=Math.round(h*dpr);
  const c=cv.getContext('2d'),P={l:18,r:74,t:15,b:30},cw=w-P.l-P.r,ch=h-P.t-P.b;
  const closes=d.map(v=>v.close),ma20=ema(closes,20),ma50=ema(closes,50),ma200=ema(closes,200);
  const values=d.flatMap(v=>[v.low,v.high]);[ma20,ma50,ma200].forEach(a=>a.forEach(v=>{if(Number.isFinite(v))values.push(v)}));
  let lo=Math.min(...values),hi=Math.max(...values),margin=(hi-lo||1)*.075;lo-=margin;hi+=margin;
  const x=i=>P.l+i/(d.length-1)*cw,y=v=>P.t+ch-(v-lo)/(hi-lo)*ch;
  c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,w,h);c.font='11px system-ui';c.lineWidth=1;c.strokeStyle='rgba(144,169,199,.14)';c.fillStyle='#75849a';
  for(let g=0;g<5;g++){const yy=P.t+g*ch/4;c.beginPath();c.moveTo(P.l,yy);c.lineTo(P.l+cw,yy);c.stroke();c.fillText((hi-(hi-lo)*g/4).toFixed(2),P.l+cw+9,yy+4)}
  const candleWidth=Math.max(2,Math.min(14,cw/d.length*.64)),lines=state.chartLines||{ma20:true,ma50:true,ma200:true},series=state.chartSeries||{candles:true,close:false};
  if(series.candles)d.forEach((v,i)=>{const xx=x(i),up=v.close>=v.open,color=up?'#28c76f':'#ef4d78',bodyTop=y(Math.max(v.open,v.close)),bodyBottom=y(Math.min(v.open,v.close)),bodyHeight=Math.max(1.5,bodyBottom-bodyTop);c.strokeStyle=color;c.fillStyle=color;c.lineWidth=1.15;c.beginPath();c.moveTo(xx,y(v.high));c.lineTo(xx,y(v.low));c.stroke();c.fillRect(Math.round(xx-candleWidth/2),bodyTop,Math.max(1,candleWidth),bodyHeight);
    const full=Math.max(v.high-v.low,.01),body=Math.abs(v.close-v.open),upper=v.high-Math.max(v.open,v.close),lower=Math.min(v.open,v.close)-v.low;
    const hammer=lower/full>.52&&upper/full<.2&&body/full<.32,star=upper/full>.52&&lower/full<.2&&body/full<.32;
    if((hammer||star)&&candleWidth>=4){c.save();c.fillStyle=hammer?'#55d9ff':'#ffc35b';c.font='700 10px system-ui';c.textAlign='center';c.fillText(hammer?'H':'S',xx,hammer?Math.min(P.t+ch-3,y(v.low)+14):Math.max(P.t+10,y(v.high)-7));c.restore()}
  });
  /* Bright blue close-price trace with a contrast outline: readable in both themes. */
  if(series.close){c.save();c.beginPath();d.forEach((v,i)=>i?c.lineTo(x(i),y(v.close)):c.moveTo(x(i),y(v.close)));c.strokeStyle='rgba(10,22,42,.72)';c.lineWidth=4.4;c.stroke();c.strokeStyle='#31b8ff';c.lineWidth=2.25;c.stroke();c.restore()}
  const line=(a,color,enabled)=>{if(!enabled)return;c.beginPath();let started=false;a.forEach((v,i)=>{if(!Number.isFinite(v)){started=false;return}if(started)c.lineTo(x(i),y(v));else{c.moveTo(x(i),y(v));started=true}});c.strokeStyle=color;c.lineWidth=1.35;c.stroke()};line(ma20,'#4b9fff',lines.ma20);line(ma50,'#d69b2d',lines.ma50);line(ma200,'#a970ff',lines.ma200);
  const hiI=d.reduce((best,v,i)=>v.high>d[best].high?i:best,0),loI=d.reduce((best,v,i)=>v.low<d[best].low?i:best,0);
  for(const [i,value,color] of [[hiI,d[hiI].high,'#ffcb65'],[loI,d[loI].low,'#52d5f4']]){const xx=x(i),yy=y(value);c.save();c.strokeStyle=color+'99';c.setLineDash([4,4]);c.beginPath();c.moveTo(P.l,yy);c.lineTo(P.l+cw,yy);c.stroke();c.setLineDash([]);c.fillStyle='#15202d';c.strokeStyle=color;c.lineWidth=2;c.beginPath();c.arc(xx,yy,5,0,Math.PI*2);c.fill();c.stroke();c.restore()}
  for(let g=0;g<5;g++){const i=Math.round(g*(d.length-1)/4);c.fillStyle='#75849a';c.textAlign='center';c.fillText(time(d[i].time),x(i),h-8)}
  if(chartSelection){const a=Math.min(chartSelection.start,chartSelection.end),b=Math.max(chartSelection.start,chartSelection.end);c.fillStyle='rgba(75,159,255,.13)';c.fillRect(x(a),P.t,x(b)-x(a),ch);c.strokeStyle='rgba(135,190,255,.9)';c.setLineDash([4,4]);c.strokeRect(x(a),P.t,x(b)-x(a),ch);c.setLineDash([])}
  if(hoverIndex!==null){const v=d[hoverIndex],xx=x(hoverIndex),yy=y(v.close);c.save();c.strokeStyle='rgba(222,237,255,.42)';c.setLineDash([3,4]);c.beginPath();c.moveTo(xx,P.t);c.lineTo(xx,P.t+ch);c.moveTo(P.l,yy);c.lineTo(P.l+cw,yy);c.stroke();c.setLineDash([]);c.fillStyle='#fff';c.beginPath();c.arc(xx,yy,3.5,0,Math.PI*2);c.fill();c.restore()}
  renderRangeExtremaPoints();
}
