function renderRangeExtremaPoints(){const box=$('chart')?.closest('.chart-box'),cv=$('chart'),d=visibleCandles();if(!box||!cv||d.length<2)return;let high=$('rangeHighPoint'),low=$('rangeLowPoint');if(!high){high=document.createElement('div');high.id='rangeHighPoint';high.className='range-extreme high';box.append(high)}if(!low){low=document.createElement('div');low.id='rangeLowPoint';low.className='range-extreme low';box.append(low)}const hiI=d.reduce((best,v,i)=>v.high>d[best].high?i:best,0),loI=d.reduce((best,v,i)=>v.low<d[best].low?i:best,0),hi=d[hiI].high,lo=d[loI].low,rect=cv.getBoundingClientRect(),P={l:18,r:74,t:15,b:30},cw=rect.width-P.l-P.r,ch=rect.height-P.t-P.b,pad=(hi-lo||1)*.075,y=v=>P.t+ch-(v-(lo-pad))/(hi-lo+pad*2)*ch,x=i=>P.l+i/(d.length-1)*cw,label=state.range||state.interval;const point=(el,i,value,kind)=>{el.style.left=`${Math.max(8,Math.min(rect.width-160,x(i)))}px`;el.style.top=`${Math.max(6,Math.min(rect.height-28,y(value)+(kind==='high'?-25:8)))}px`;el.textContent=`${label}${kind==='high'?tx('最高点',' high'):tx('最低点',' low')} ${money(value)} · ${pointTime(d[i].time)}`};point(high,hiI,hi,'high');point(low,loI,lo,'low')}
