draw=function(){drawWithExtremaDots();const cv=$('chart'),d=visibleCandles();if(!cv||d.length<2)return;const rect=cv.getBoundingClientRect(),P={l:18,r:74,t:15,b:30},cw=rect.width-P.l-P.r,ch=rect.height-P.t-P.b,closes=d.map(v=>v.close),averages=[ema(closes,20),ema(closes,50),ema(closes,200)],values=d.flatMap(v=>[v.low,v.high]);averages.forEach(a=>a.forEach(v=>{if(Number.isFinite(v))values.push(v)}));let lo=Math.min(...values),hi=Math.max(...values),margin=(hi-lo||1)*.075;lo-=margin;hi+=margin;const x=i=>P.l+i/(d.length-1)*cw,y=v=>P.t+ch-(v-lo)/(hi-lo)*ch,hiI=d.reduce((best,v,i)=>v.high>d[best].high?i:best,0),loI=d.reduce((best,v,i)=>v.low<d[best].low?i:best,0),c=cv.getContext('2d'),dpr=devicePixelRatio||1;for(const [i,value,color] of [[hiI,d[hiI].high,'#ffcb65'],[loI,d[loI].low,'#52d5f4']]){c.save();c.setTransform(dpr,0,0,dpr,0,0);c.fillStyle='#15202d';c.strokeStyle=color;c.lineWidth=2;c.beginPath();c.arc(x(i),y(value),5,0,Math.PI*2);c.fill();c.stroke();c.fillStyle=color;c.beginPath();c.arc(x(i),y(value),2,0,Math.PI*2);c.fill();c.restore()}};

/* Empirical liquidation-risk calculator (historical volatility, not a guarantee). */
const liqProbState=JSON.parse(localStorage.getItem('btc_liq_probability')||'{"exchange":"okx","side":"long","amount":1000,"leverage":10,"entry":0}');
function calcLiqProbability(){const form=$('liqProbabilityForm'),out=$('liqProbabilityOutput');if(!form||!out)return;const p=liqProbState,entry=+p.entry||state.ticker?.last||0,amount=Math.max(0,+p.amount||0),lev=Math.max(1,+p.leverage||1),side=p.side==='short'?-1:1,mmr={binance:.004,okx:.005,coinbase:.006}[p.exchange]||.005,fee={binance:.0005,okx:.0005,coinbase:.0006}[p.exchange]||.0005,liq=side>0?entry*(1-1/lev+mmr):entry*(1+1/lev-mmr),distance=Math.abs(liq-entry)/entry,d=state.candles.slice(-120),window=20;let hits=0,total=0;for(let i=0;i+window<=d.length;i++){const start=d[i].close,adverse=side>0?(start-Math.min(...d.slice(i,i+window).map(x=>x.low)))/start:(Math.max(...d.slice(i,i+window).map(x=>x.high))-start)/start;hits+=adverse>=distance?1:0;total++}const probability=total?hits/total*100:0,level=probability>=25?'bear':probability>=10?'flat':'bull',direction=side>0?tx('做多','Long'):tx('做空','Short');out.innerHTML=`<div><small>${tx('理论强平价','Theoretical liquidation')}</small><b class="bear">${money(liq)}</b></div><div><small>${tx('距成本价','Distance from entry')}</small><b>${(distance*100).toFixed(2)}%</b></div><div><small>${tx('历史触及频率','Historical touch frequency')}</small><b class="${level}">${probability.toFixed(2)}%</b></div><div><small>${tx('手续费参考（开+平）','Fee reference (in + out)')}</small><b>${money(amount*fee*2)}</b></div><p class="${level}">${direction} · ${tx('基于最近','Based on recent')} ${total} ${tx('个','')} ${window}${tx(' 根 K 线窗口的历史震荡；这不是未来真实概率。','-candle volatility windows; this is not a future probability.')}</p>`}
(() => {const host=document.querySelector('.micro-forecast');if(!host||$('liqProbabilityCard'))return;const card=document.createElement('section');card.id='liqProbabilityCard';card.className='liq-probability';card.innerHTML=`<div class="liq-prob-head"><h3>${tx('强平概率计算器','Liquidation probability calculator')}</h3><span>${tx('历史震荡估算','Historical volatility estimate')}</span></div><form id="liqProbabilityForm" class="liq-prob-form"><label>${tx('交易所','Exchange')}<select name="exchange"><option value="okx">OKX</option><option value="binance">Binance</option><option value="coinbase">Coinbase</option></select></label><label>${tx('方向','Side')}<select name="side"><option value="long">${tx('做多','Long')}</option><option value="short">${tx('做空','Short')}</option></select></label><label>${tx('购买数量（USDT）','Purchase amount (USDT)')}<input name="amount" type="number" min="0" step="0.01"></label><label>${tx('杠杆倍率','Leverage')}<select name="leverage">${[1,2,3,5,10,20,30,50,100].map(x=>`<option value="${x}">${x}×</option>`).join('')}</select></label><label>${tx('成本价','Entry cost')}<input name="entry" type="number" min="0" step="0.01"></label></form><div id="liqProbabilityOutput" class="liq-prob-output"></div>`;host.append(card);const form=$('liqProbabilityForm');Object.entries(liqProbState).forEach(([k,v])=>{if(form.elements[k])form.elements[k].value=v});form.oninput=()=>{for(const el of form.elements)if(el.name)liqProbState[el.name]=el.value;localStorage.setItem('btc_liq_probability',JSON.stringify(liqProbState));calcLiqProbability()};calcLiqProbability()})();
const renderAnalysisWithLiqProbability=renderAnalysis;
renderAnalysis=function(){renderAnalysisWithLiqProbability();if(!liqProbState.entry&&state.ticker){liqProbState.entry=state.ticker.last;const f=$('liqProbabilityForm');if(f&&document.activeElement!==f.elements.entry)f.elements.entry.value=liqProbState.entry}calcLiqProbability()};

/* Digit-level ticker animation: the first changed digit and every lower place flash. */
let renderedPriceText=null;
const renderTickerWithWholeFlash=renderTicker;
renderTicker=function(){const before=previousTickerPrice;renderTickerWithWholeFlash();const t=state.ticker,price=$('price'),change=$('change');if(!t||!price)return;const value=money(t.last),prior=renderedPriceText;let first=-1;if(prior!==null){if(prior.length!==value.length)first=0;else{for(let i=0;i<value.length;i++){if(/\d/.test(value[i])&&value[i]!==prior[i]){first=i;break}}}}const direction=before===null||t.last===before?'':t.last>before?'up':'down';price.classList.remove('price-up','price-down');price.innerHTML=[...value].map((ch,i)=>`<span class="${/\d/.test(ch)?'price-digit':''} ${first>=0&&i>=first&&/\d/.test(ch)?`changed-${direction}`:''}">${ch}</span>`).join('');if(change)change.classList.remove('price-up','price-down');renderedPriceText=value};

