function renderPatternAnalysis(){const d=state.candles;if(d.length<25)return;let card=$('patternAnalysis');if(!card){card=document.createElement('section');card.id='patternAnalysis';card.className='card pattern-analysis-card';const anchor=document.querySelector('.terminal-layout');if(anchor)anchor.after(card);else document.querySelector('main')?.append(card)}const closes=d.map(x=>x.close),ma5=ema(closes,5).at(-1),ma10=ema(closes,10).at(-1),ma20=ema(closes,20).at(-1),last=d.at(-1),prior=d.slice(-Math.min(21,d.length),-1),high=Math.max(...prior.map(x=>x.high)),low=Math.min(...prior.map(x=>x.low)),range=Math.max(last.high-last.low,.01),upper=(last.high-Math.max(last.open,last.close))/range,lower=(Math.min(last.open,last.close)-last.low)/range,meanVol=prior.reduce((sum,x)=>sum+x.volume,0)/Math.max(1,prior.length),volumeRatio=meanVol?last.volume/meanVol:1,bullStack=ma5>ma10&&ma10>ma20,bearStack=ma5<ma10&&ma10<ma20,above=last.close>ma5&&last.close>ma10&&last.close>ma20,breakout=last.close>high,breakdown=last.close<low,trend=bullStack&&above?(breakout||volumeRatio>=1.5?tx('放量突破后强势整理','Post-breakout consolidation'):tx('均线多头排列，短线偏强','Bullish moving-average alignment')):bearStack&&!above?(breakdown||volumeRatio>=1.5?tx('跌破整理区，短线偏弱','Breakdown below consolidation'):tx('均线空头排列，短线偏弱','Bearish moving-average alignment')):tx('区间震荡，等待方向确认','Range-bound; waiting for confirmation'),trendClass=bullStack&&above?'bull':bearStack&&!above?'bear':'flat',wick=upper>=.42?tx('长上影：高位抛压需留意','Long upper wick: overhead selling pressure'):lower>=.42?tx('长下影：下方承接出现','Long lower wick: lower-price demand appeared'):tx('影线中性，暂无明显单根反转形态','Neutral wick; no strong one-candle reversal'),supportA=bullStack?ma5:ma10,supportB=bullStack?ma10:low,resistance=bullStack?high:ma20,invalid=bullStack?Math.min(ma20,low):Math.max(ma20,high),scenario=bullStack&&above?tx(`若守住 ${money(supportA)} 附近，才有机会再次测试 ${money(resistance)}；若跌破 ${money(invalid)}，短线强势结构会被削弱。`,`Holding near ${money(supportA)} keeps a retest of ${money(resistance)} possible; a break below ${money(invalid)} weakens the short-term structure.`):bearStack&&!above?tx(`若反抽未能站回 ${money(resistance)}，弱势可能延续；若重新站上 ${money(invalid)}，空头结构会被削弱。`,`Failure to recover ${money(resistance)} can prolong weakness; moving back above ${money(invalid)} weakens the bearish structure.`):tx(`重点观察 ${money(low)} 至 ${money(high)} 区间的有效突破，并结合成交量确认。`,`Watch for a confirmed break of the ${money(low)}–${money(high)} range with volume confirmation.`);const html=`<div class="pattern-head"><div><h2>${tx('形态识别与关键位','Pattern recognition & key levels')} <button class="help-dot" type="button" data-tip="${tx('该卡片仅将当前 K 线、均线、成交量与近期区间转为研究性描述。它不预测确定涨跌，也不构成投资建议。','This card turns current candles, moving averages, volume and recent ranges into research descriptions. It does not predict certain outcomes or provide investment advice.')}">!</button></h2><p>${tx(`基于当前 ${state.interval} K 线 · 研究解读，非投资建议`,`Based on current ${state.interval} candles · research only, not investment advice`)}</p></div><span class="pattern-state ${trendClass}">${trend}</span></div><div class="pattern-grid"><article><small>${tx('趋势与均线','Trend & moving averages')}</small><b class="${trendClass}">${bullStack?tx('MA5 / 10 / 20 多头排列','MA5 / 10 / 20 bullish stack'):bearStack?tx('MA5 / 10 / 20 空头排列','MA5 / 10 / 20 bearish stack'):tx('均线交错','Mixed moving averages')}</b><em>MA5 ${money(ma5)} · MA10 ${money(ma10)} · MA20 ${money(ma20)}</em></article><article><small>${tx('近期关键高 / 低','Recent high / low')}</small><b>${money(high)} <i>${tx('高','High')}</i>　${money(low)} <i>${tx('低','Low')}</i></b><em>${tx('统计窗口：前 20 根 K 线（不含当前）','Window: prior 20 candles, excluding current')}</em></article><article><small>${tx('当前 K 线信号','Current-candle signal')}</small><b class="${upper>=.42?'bear':lower>=.42?'bull':'flat'}">${wick}</b><em>${tx('当前成交量 / 近 20 根均量','Current volume / 20-candle average')} ${volumeRatio.toFixed(2)}×</em></article></div><div class="pattern-levels"><span><small>${tx('阻力参考','Resistance')}</small><b class="bear">${money(resistance)}</b></span><span><small>${tx('短线支撑','Near support')}</small><b class="bull">${money(supportA)}</b></span><span><small>${tx('关键支撑','Key support')}</small><b class="bull">${money(supportB)}</b></span><span><small>${tx('结构失效参考','Structure invalidation')}</small><b class="flat">${money(invalid)}</b></span></div><p class="pattern-scenario"><b>${tx('情景观察：','Scenario watch:')}</b> ${scenario}</p>`;if(card.innerHTML!==html)card.innerHTML=html}
