function renderPatternNarrative(){const card=$('patternAnalysis'),d=state.candles;if(!card||d.length<25)return;const closes=d.map(x=>x.close),ma5=ema(closes,5).at(-1),ma10=ema(closes,10).at(-1),ma20=ema(closes,20).at(-1),last=d.at(-1),prior=d.slice(-Math.min(21,d.length),-1),high=Math.max(...prior.map(x=>x.high)),low=Math.min(...prior.map(x=>x.low)),bull=ma5>ma10&&ma10>ma20&&last.close>ma20,bear=ma5<ma10&&ma10<ma20&&last.close<ma20,resistance=bull?high:ma20,support=bull?ma5:ma10,invalid=bull?Math.min(ma20,low):Math.max(ma20,high);let box=$('patternNarrative');if(!box){box=document.createElement('div');box.id='patternNarrative';box.className='pattern-narrative';card.append(box)}const script=bull?`<ol><li>${tx(`先观察 ${money(support)} 至 ${money(resistance)} 的整理 / 回踩。`,`Watch for consolidation or a pullback between ${money(support)} and ${money(resistance)}.`)}</li><li>${tx(`若支撑守住且量能恢复，才具备再次测试 ${money(resistance)} 的条件。`,`If support holds and volume returns, a retest of ${money(resistance)} becomes possible.`)}</li><li>${tx(`若跌破 ${money(invalid)}，短线多头结构转弱。`,`A break below ${money(invalid)} weakens the short-term bullish structure.`)}</li></ol>`:bear?`<ol><li>${tx(`先观察反抽是否受制于 ${money(resistance)}。`,`Watch whether rebounds are capped near ${money(resistance)}.`)}</li><li>${tx(`若无法站回该位置，可能继续测试 ${money(support)} 附近。`,`Failure to recover that level may lead to a test near ${money(support)}.`)}</li><li>${tx(`若重新站上 ${money(invalid)}，空头结构会被削弱。`,`A move above ${money(invalid)} weakens the bearish structure.`)}</li></ol>`:`<ol><li>${tx(`先观察 ${money(low)} 至 ${money(high)} 区间内的震荡。`,`Watch the range between ${money(low)} and ${money(high)}.`)}</li><li>${tx('只有突破区间并伴随成交量确认，方向判断才更有意义。','A directional view becomes more meaningful only after a range break with volume confirmation.')}</li><li>${tx('区间中部信号质量通常较低，避免把单根 K 线当成趋势确认。','Signals near the middle of a range are weaker; do not treat one candle as trend confirmation.')}</li></ol>`;box.innerHTML=`<article><h3>${tx('短线剧本','Short-term scenario')}</h3>${script}</article><article><h3>${tx('观察建议','What to watch')}</h3><ul><li>${tx(`支撑 / 阻力：${money(support)} / ${money(resistance)}`,`Support / resistance: ${money(support)} / ${money(resistance)}`)}</li><li>${tx('核心确认：下一 1–3 根 K 线的收盘位置与成交量变化。','Core confirmation: closes and volume over the next 1–3 candles.')}</li><li>${tx(`结构失效参考：${money(invalid)}；仅作研究观察，不构成交易指令。`,`Structure invalidation reference: ${money(invalid)}; research context only, not a trade instruction.`)}</li></ul></article>`}
